<section class="capture-list" aria-label="Captures" data-capture-list><?php if(!$captures): ?><div class="empty-state"><div class="empty-glyph">C</div><h2>Nothing here yet</h2><p>Captures matching this view will appear here.</p></div><?php endif; ?><?php foreach($captures as $capture): $icon=match($capture['type']){'url'=>'link','image'=>'image','audio'=>'voice',default=>'text'}; ?><article class="capture-row"><input class="capture-select" type="checkbox" value="<?=htmlspecialchars($capture['id'])?>" aria-label="Select capture #<?=(int)$capture['catch_number']?>"><span class="type-icon" aria-hidden="true"><i class="glyph glyph-<?=htmlspecialchars($icon)?>"></i></span><div class="capture-copy"><a class="capture-title-link" href="/captures/<?=urlencode($capture['id'])?>"><strong><?=htmlspecialchars($capture['title']?:mb_strimwidth($capture['text']?:$capture['url']?:'Attachment',0,90,'…'))?></strong></a><div class="capture-subline"><span class="capture-meta"><span class="capture-number">#<?=(int)$capture['catch_number']?></span><span aria-hidden="true"> · </span><time datetime="<?=htmlspecialchars(str_replace(' ','T',substr($capture['created_at'],0,19)).'Z')?>" data-local-time data-date-style="medium" data-time-style="short">UTC <?=htmlspecialchars($capture['created_at'])?></time></span><?php if(!empty($capture['tags'])): ?><span class="capture-row-tags"><?php foreach($capture['tags'] as $tag): ?><a class="tag-link" href="<?=htmlspecialchars($tag['url'])?>"><?=htmlspecialchars($tag['name'])?></a><?php endforeach; ?></span><?php endif; ?></div></div><form method="post" action="/captures/<?=urlencode($capture['id'])?>/<?=$status==='archived'?'delete':'archive'?>"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><button class="icon-button" type="submit" aria-label="<?=$status==='archived'?'Delete':'Archive'?>"><?=$status==='archived'?'×':'✓'?></button></form></article><?php endforeach; ?></section>
